  "claim": {
    "component_id": "C009.component",
    "value": "Delayed collection is a possible contributor to late starts.",
    "scope": "A hypothesis to investigate, not an established contributor.",
    "provenance": {
      "refs": [
        {
          "source_id": "P003",
          "role": "SUPPORT"
        },
        {
          "source_id": "P002",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P003 explicitly identifies delayed collection as a hypothesized contributor; P002 identifies late starts as the problem."
    }
  },
  "signal_basis": {
    "component_id": "C009.signal_basis",
    "value": "Comparable event records reveal repeated late collection after documented readiness, with equipment ready but uncollected at scheduled starts.",
    "scope": "Assumed observed for this judgment. Ambiguous cases remain unresolved, and collection is not equated with actual start without verification. The pattern supports investigation, not causal identification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
